class ApronMaleFace extends StatelessWidget {
  final ApronMaleFaceType type;
  final ApronMaleFaceExpression expression;
  final double? width;
  final double? height;
  final ColorMapper? colorMapper;

  const ApronMaleFace({
    required this.type,
    required this.expression,
    this.width,
    this.height,
    this.colorMapper,
    super.key,
  });

  @override
  Widget build(BuildContext context) {
    late String svgString;
    switch (expression) {
      case ApronMaleFaceExpression.default_:
        switch (type) {
          case ApronMaleFaceType.a:
            svgString = _maleFaceTypeADefault;
          case ApronMaleFaceType.b:
            svgString = _maleFaceTypeBDefault;
          case ApronMaleFaceType.c:
            svgString = _maleFaceTypeCDefault;
        }
      case ApronMaleFaceExpression.question:
        switch (type) {
          case ApronMaleFaceType.a:
            svgString = _maleFaceTypeAQuestion;
          case ApronMaleFaceType.b:
            svgString = _maleFaceTypeBQuestion;
          case ApronMaleFaceType.c:
            svgString = _maleFaceTypeCQuestion;
        }
      case ApronMaleFaceExpression.surprised:
        switch (type) {
          case ApronMaleFaceType.a:
            svgString = _maleFaceTypeASurprised;
          case ApronMaleFaceType.b:
            svgString = _maleFaceTypeBSurprised;
          case ApronMaleFaceType.c:
            svgString = _maleFaceTypeCSurprised;
        }
      case ApronMaleFaceExpression.sad:
        switch (type) {
          case ApronMaleFaceType.a:
            svgString = _maleFaceTypeASad;
          case ApronMaleFaceType.b:
            svgString = _maleFaceTypeBSad;
          case ApronMaleFaceType.c:
            svgString = _maleFaceTypeCSad;
        }
      case ApronMaleFaceExpression.worry:
        switch (type) {
          case ApronMaleFaceType.a:
            svgString = _maleFaceTypeAWorry;
          case ApronMaleFaceType.b:
            svgString = _maleFaceTypeBWorry;
          case ApronMaleFaceType.c:
            svgString = _maleFaceTypeCWorry;
        }
      case ApronMaleFaceExpression.facedown:
        switch (type) {
          case ApronMaleFaceType.a:
            svgString = _maleFaceTypeAFacedown;
          case ApronMaleFaceType.b:
            svgString = _maleFaceTypeBFacedown;
          case ApronMaleFaceType.c:
            svgString = _maleFaceTypeCFacedown;
        }
      case ApronMaleFaceExpression.tilt:
        switch (type) {
          case ApronMaleFaceType.a:
            svgString = _maleFaceTypeATilt;
          case ApronMaleFaceType.b:
            svgString = _maleFaceTypeBTilt;
          case ApronMaleFaceType.c:
            svgString = _maleFaceTypeCTilt;
        }
    }
    return SvgPicture.string(
      svgString,
      height: height,
      width: width,
      colorMapper: colorMapper,
    );
  }
